    public val all: Set<String> get() = calls.keys

    public suspend fun call(method: String, gateway: HermesGateway, params: JsonElement, json: Json): JsonElement =
        (calls[method] ?: throw LiveScenarioFailure("No generated gateway method $method"))(gateway, params, json)

    /** Decodes a recorded result through the method's generated type and re-encodes it. */
    public fun decodeResult(method: String, result: JsonElement, json: Json): JsonElement =
        (results[method] ?: throw LiveScenarioFailure("No generated gateway method $method"))(result, json)
}
